<template><el-card shadow="never"><el-alert title="建议上传 1920×640px 图片，单张不超过 2MB，最多上传 9 张" type="info" show-icon/><div class="banner-grid"><div v-for="(image,i) in images" :key="image" class="banner-item"><el-image :src="image" fit="cover"/><el-button circle size="small" type="danger" @click="remove(i)">×</el-button></div><label v-if="images.length<9" class="upload"><input type="file" accept="image/*" multiple @change="upload"/><span>+</span><small>上传轮播图</small></label></div><el-button type="primary" @click="save">保存设置</el-button></el-card></template><script setup lang="ts" name="websiteBanner">const images=ref<string[]>(['https://images.unsplash.com/photo-1544145945-f90425340c7e?auto=format&fit=crop&w=960&q=80']);const upload=(e:Event)=>Array.from((e.target as HTMLInputElement).files||[]).slice(0,9-images.value.length).forEach(f=>images.value.push(URL.createObjectURL(f)));const remove=(i:number)=>images.value.splice(i,1);const save=()=>ElMessage.success('Banner设置已保存')</script><style scoped>.banner-grid{display:flex;flex-wrap:wrap;gap:16px;margin:24px 0}.banner-item,.upload{position:relative;width:240px;height:100px}.banner-item :deep(.el-image){width:100%;height:100%;border-radius:6px}.banner-item .el-button{position:absolute;top:-10px;right:-10px}.upload{display:flex;flex-direction:column;align-items:center;justify-content:center;border:1px dashed var(--el-border-color);cursor:pointer}.upload input{display:none}.upload span{font-size:28px}</style>
